 49	    private static final class Edge {
 50	        private final int from;
 51	        private final int to;
 52	        private final int weight;
 53	
 54	        private Edge(int from, int to, int weight) {
 55	            this.from = from;
 56	            this.to = to;
 57	            this.weight = weight;
 58	        }
 59	
 60	        private boolean isWithin(int vertexCount) {
 61	            return from >= 0 && from < vertexCount && to >= 0 && to < vertexCount;
 62	        }
 63	
 64	        private boolean relax(Distances distances) {
 65	            return distances.relax(from, to, weight);
 66	        }
 67	
 68	        private boolean canRelax(Distances distances) {
 69	            return distances.canRelax(from, to, weight);
 70	        }
 71	    }
 72	
 73	    private static final class Distances {
 74	        private final int[] values;
 75	
 76	        private Distances(int vertexCount, int source) {
 77	            values = new int[vertexCount];
 78	            Arrays.fill(values, INF);
 79	            values[source] = 0;
 80	        }
 81	
 82	        private boolean relax(int from, int to, int weight) {
 83	            if (!canRelax(from, to, weight)) {
 84	                return false;
 85	            }
 86	
 87	            values[to] = values[from] + weight;
 88	            return true;
 89	        }
 90	
 91	        private boolean canRelax(int from, int to, int weight) {
 92	            return values[from] != INF && values[from] + weight < values[to];
 93	        }
 94	
 95	        private int[] toArray() {
 96	            return Arrays.copyOf(values, values.length);
 97	        }
 98	    }
