100	    private static final class Graph {
101	        private final int vertexCount;
102	        private final Edge[] edges;
103	
104	        private Graph(int vertexCount, Edge[] edges) {
105	            this.vertexCount = vertexCount;
106	            this.edges = edges;
107	        }
108	
109	        private static Graph from(int vertexCount, int[][] edgeData) {
110	            if (vertexCount < 0) {
111	                throw new IllegalArgumentException("Vertex count cannot be negative");
112	            }
113	
114	            if (edgeData == null) {
115	                throw new IllegalArgumentException("Edges cannot be null");
116	            }
117	
118	            Edge[] edges = new Edge[edgeData.length];
119	            for (int i = 0; i < edgeData.length; i++) {
120	                edges[i] = parseEdge(vertexCount, edgeData[i], i);
121	            }
122	
123	            return new Graph(vertexCount, edges);
124	        }
125	
126	        private static Edge parseEdge(int vertexCount, int[] edgeData, int index) {
127	            if (edgeData == null || edgeData.length != EDGE_FIELD_COUNT) {
128	                throw new IllegalArgumentException("Edge " + index + " must contain from, to, and weight");
129	            }
130	
131	            Edge edge = new Edge(edgeData[FROM_INDEX], edgeData[TO_INDEX], edgeData[WEIGHT_INDEX]);
132	            if (!edge.isWithin(vertexCount)) {
133	                throw new IllegalArgumentException("Edge " + index + " references a vertex outside the graph");
134	            }
135	
136	            return edge;
137	        }
138	
139	        private void validateSource(int source) {
140	            if (source < 0 || source >= vertexCount) {
141	                throw new IllegalArgumentException("Source vertex is out of range");
142	            }
143	        }
144	
145	        private Distances initialDistances(int source) {
146	            return new Distances(vertexCount, source);
147	        }
148	
149	        private int relaxationPasses() {
150	            return Math.max(0, vertexCount - 1);
151	        }
152	
153	        private boolean relaxEdges(Distances distances) {
154	            boolean changed = false;
155	
156	            for (Edge edge : edges) {
157	                if (edge.relax(distances)) {
158	                    changed = true;
159	                }
160	            }
161	
162	            return changed;
163	        }
164	
165	        private boolean hasReachableNegativeCycle(Distances distances) {
166	            for (Edge edge : edges) {
167	                if (edge.canRelax(distances)) {
168	                    return true;
169	                }
170	            }
171	
172	            return false;
173	        }
174	    }
